// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Each code point includes lone surrogates. Each block starts with FNV offset 2166136261.
// Feed one UTF-16 '0'/'1' unit per result, in u, v order for each code point.
const pattern0 = /^\p{Case_Ignorable}$/u;
const pattern1 = /^\p{Case_Ignorable}$/v;
const expected: number[] = [
  0xf761fa8f, 0xdafb43c3, 0xdf20de27, 0x908de13d, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0x80f94a5d, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xdc48ba39,
  0xf2b7bdc9, 0x7427c2fb, 0xfa431dc5, 0xb1a02645, 0xfa431dc5, 0xfa431dc5, 0x62d682fd, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0x5dd74a87, 0xde5cb9d1, 0xb0d406e7, 0xeabb8715, 0xbfb059ad, 0x6f298857,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
];
assert.sameValue(expected.length, 64);
for (let block = 0x000000; block < 0x040000; block += 4096) {
  let hash = 2166136261;
  for (let cp = block; cp < block + 4096; cp++) {
    const input = String.fromCodePoint(cp);
    hash = Math.imul(hash ^ (pattern0.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (pattern1.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
  }
  assert.sameValue(hash, expected[(block - 0x000000) / 4096], "Case_Ignorable block U+" + block.toString(16));
}
